// Build the daily message.
//
// docs/workflows.md on WF-100: "The awaiting-approval count is the number that
// matters. A growing queue means the human is the bottleneck, which is the
// intended state early on." So it goes first, and it is never buried in a list.
//
// This node formats. It decides nothing and hides nothing: if the pipeline did
// nothing yesterday, the report says so in one line rather than going quiet.

const f = $input.first().json ?? {};
const stats = f.stats ?? {};
const totals = f.totals ?? {};
const pipeline = f.pipeline ?? {};
const hot = Array.isArray(f.hot_companies) ? f.hot_companies : [];
const opps = Array.isArray(f.opportunities) ? f.opportunities : [];
const agents = Array.isArray(f.agents) ? f.agents : [];

function n(v) {
  const x = Number(v);
  return Number.isFinite(x) ? x : 0;
}

const awaiting = n(stats.awaiting_approval);
const lines = [];
const k = f.kpis ?? {};
const segments = Array.isArray(f.segments) ? f.segments : [];

// The number this phase is judged on goes first (2026-09-29): people who
// answered with interest, a question, a price request or a referral, or who
// reached a meeting. Everything else explains it.
lines.push('Sales conversations: ' + n(k.sales_conversations) +
           ' (meetings ' + n(k.meetings) + ', proposals ' + n(k.proposals) + ', clients ' + n(k.clients) + ')');
lines.push('  contacted ' + n(k.leads_contacted) + ' · replied ' + n(k.replied) +
           ' · bounced ' + n(k.bounced) + ' · unsubscribed ' + n(k.unsubscribed) +
           ' · pipeline €' + n(k.pipeline_eur));
const tried = segments.filter((s) => n(s.contacted) > 0 || n(s.qualified) > 0);
if (tried.length > 0) {
  lines.push('  by segment (qualified / contacted / replied / conversations):');
  for (const s of tried) {
    lines.push('    ' + s.segment + ': ' + n(s.qualified) + ' / ' + n(s.contacted) + ' / ' +
               n(s.replied) + ' / ' + n(s.conversations));
  }
}
lines.push('');

lines.push('Awaiting your approval: ' + awaiting);
if (awaiting === 0) {
  lines.push('  Nothing to read. Either nothing scored high enough, or no drafts were generated.');
}
lines.push('');

// Guarded autosend (0030_autosend.sql): every message that went out without
// the operator's approval, by name, so a human reads each one after the fact - the
// condition for turning it on on 2026-10-08. Shown whenever autosend
// is or was in play; silent when it never was.
const autosent = Array.isArray(f.autosent) ? f.autosent : [];
const autosendEnv = String($env.OUTREACH_AUTOSEND_ENABLED ?? 'false').trim() === 'true';
const autosendOn = autosendEnv && f.autosend_enabled === true;
if (autosendOn || autosent.length > 0 || n(f.autosend_waiting) > 0) {
  lines.push('Poslato automatski (poslednja 24h): ' + autosent.length +
             (autosendOn ? '' : ' · autosend je sada isključen'));
  for (const a of autosent.slice(0, 40)) {
    lines.push('  ' + a.lead + '  ' + a.company + ' — ' + (a.subject || '(no subject)') +
               (a.status && a.status !== 'sent' ? ' [' + a.status + ']' : ''));
  }
  if (autosent.length > 40) lines.push('  ... and ' + (autosent.length - 40) + ' more');
  if (n(f.autosend_waiting) > 0) {
    lines.push('  odobreno automatski, čeka slanje: ' + n(f.autosend_waiting));
  }
  lines.push('  /stop isključuje autosend · /autosend pokazuje stanje');
  lines.push('');
}

lines.push('Last 24 hours');
lines.push('  discovered  ' + n(stats.companies_discovered));
lines.push('  signals     ' + n(stats.signals_captured));
lines.push('  leads       ' + n(stats.leads_created));
lines.push('  sent        ' + n(stats.messages_sent));
lines.push('  replies     ' + n(stats.replies_received));
lines.push('  failures    ' + n(stats.agent_failures));

const active = Object.entries(pipeline)
  .filter(([, v]) => n(v) > 0)
  .sort((a, b) => n(b[1]) - n(a[1]));
lines.push('');
lines.push('Pipeline (' + n(totals.companies_total) + ' companies, ' +
           n(totals.people_total) + ' people, ' + n(totals.leads_total) + ' leads)');
if (active.length === 0) {
  lines.push('  empty');
} else {
  for (const [status, count] of active) lines.push('  ' + status.padEnd(12) + n(count));
}

if (hot.length > 0) {
  lines.push('');
  lines.push('Top companies');
  for (const c of hot) {
    lines.push('  ' + c.total_score + '  ' + c.name + ' (' + c.domain + ') ' +
               c.score_band + (n(c.people) === 0 ? ' — no contact yet' : ''));
  }
}

if (n(stats.open_opportunities) > 0) {
  lines.push('');
  lines.push('Open opportunities: ' + n(stats.open_opportunities));
  for (const o of opps) {
    lines.push('  ' + o.company + ' — ' + o.person + ' (' + o.status +
               (o.reason ? ': ' + o.reason : '') + ')');
  }
}

if (agents.length > 0) {
  lines.push('');
  lines.push('Agents (24h)');
  for (const a of agents) {
    const avg = a.avg_ms === null || a.avg_ms === undefined
      ? '' : ', avg ' + Math.round(n(a.avg_ms) / 1000) + 's';
    lines.push('  ' + a.agent + ': ' + n(a.runs) + ' runs, ' + n(a.failed) + ' failed' + avg);
  }
} else {
  lines.push('');
  lines.push('Agents (24h): no runs at all. Either nothing was queued, or no workflow is active.');
}

const date = f.report_date ?? new Date().toISOString().slice(0, 10);

return [{
  json: {
    report_date: date,
    // One row per day. Re-running the report on the same day folds into that
    // row instead of sending a second copy, which is the idempotency rule in
    // docs/workflows.md.
    dedup_key: 'daily_report:' + date,
    title: 'Daily report ' + date,
    body: lines.join('\n'),
    awaiting_approval: awaiting,
    autosent_count: autosent.length,
    payload: {
      stats,
      totals,
      pipeline,
      hot_companies: hot,
      agents,
      autosent,
    },
  },
}];
